1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace AtrioTeam\DigitalHub\Filament\Forms\Components;
6	
7	use Filament\Forms\Components\Field;
8	use Illuminate\Database\Eloquent\Collection;
9	use Illuminate\Database\Eloquent\Model;
10	use Illuminate\Database\Eloquent\Relations\BelongsToMany;
11	
12	/**
13	 * Selettore a checkbox annidati: le categorie sono righe collassabili
14	 * (accordion) con un checkbox padre a tre stati; espandendo la categoria si
15	 * apre l'elenco dei suoi item come dropdown di checkbox.
16	 *
17	 * Selezionando la categoria si attivano tutti gli item; deselezionando un item
18	 * la categoria non risulta più tutta selezionata (stato indeterminate). La
19	 * relazione è salvata sempre a livello di singolo item, sincronizzando solo
20	 * gli id nell'"universo" del campo (quelli offerti come opzioni): questo
21	 * permette a più istanze di condividere la stessa relazione (es. `tags`
22	 * diviso per gruppo) senza cancellarsi a vicenda le selezioni.
23	 *
24	 * Campo generico del core: non conosce i modelli di dominio del template, che
25	 * vengono passati come class-string a {@see self::relationship()}. Categorie
26	 * e item possono anche essere iniettati già filtrati/eager-loaded tramite
27	 * {@see self::categories()} e {@see self::items()}, per i casi in cui il
28	 * chiamante deve scoparli (es. per gruppo) invece di caricare l'intera tabella.
29	 */
30	class NestedCheckboxSelect extends Field
31	{
32	    protected string $view = 'digital-hub::filament.forms.components.nested-checkbox-select';
33	
34	    /** @var class-string<Model> */
35	    protected string $itemModel;
36	
37	    /** @var class-string<Model> */
38	    protected string $categoryModel;
39	
40	    protected string $categoryForeignKey;
41	
42	    protected string $noCategoryLabel = '';
43	
44	    /**
45	     * override esplicito, bypassa la query su $categoryModel; la closure può
46	     * iniettare Get per filtrare in base allo stato reattivo del form
47	     *
48	     * @var list<Model>|\Closure|null
49	     */
50	    protected array|\Closure|null $categories = null;
51	
52	    /**
53	     * override esplicito, bypassa la query su $itemModel; la closure può
54	     * iniettare Get per filtrare in base allo stato reattivo del form
55	     *
56	     * @var list<Model>|\Closure|null
57	     */
58	    protected array|\Closure|null $items = null;
59	
60	    /**
61	     * Configura la sorgente e il salvataggio della relazione BelongsToMany.
62	     *
63	     * @param string $name nome della relazione BelongsToMany sul record ospitante
64	     * @param class-string<Model> $itemModel modello degli item (es. Material/Fabric), usato se {@see self::items()} non è impostato
65	     * @param class-string<Model> $categoryModel modello della categoria, usato se {@see self::categories()} non è impostato
66	     * @param string $categoryForeignKey FK sull'item verso la categoria
67	     * @param string $noCategoryLabel etichetta per gli item senza categoria
68	     */
69	    public function relationship(
70	        string $name,
71	        string $itemModel,
72	        string $categoryModel,
73	        string $categoryForeignKey,
74	        string $noCategoryLabel,
75	    ): static {
76	        $this->itemModel = $itemModel;
77	        $this->categoryModel = $categoryModel;
78	        $this->categoryForeignKey = $categoryForeignKey;
79	        $this->noCategoryLabel = $noCategoryLabel;
80	
81	        // lo stato è un array sintetico di id: non è una colonna del modello
82	        $this->dehydrated(false);
83	
84	        $this->loadStateFromRelationshipsUsing(static function (NestedCheckboxSelect $component, ?Model $record) use ($name): void {
85	            if ($record === null) {
86	                return;
87	            }
88	
89	            $relation = self::relationOf($record, $name);
90	            $relatedIds = $relation->pluck($relation->getRelated()->getKeyName())
91	                ->map(fn (mixed $id): string => is_numeric($id) ? (string) (int) $id : '')
92	                ->all();
93	
94	            // limitato all'universo del campo: la relazione può essere
95	            // condivisa con altre istanze filtrate su altri gruppi/categorie
96	            $component->state(array_values(array_intersect($relatedIds, $component->universeIds())));
97	        });
98	
99	        $this->saveRelationshipsUsing(static function (NestedCheckboxSelect $component, ?Model $record) use ($name): void {
100	            if ($record === null) {
101	                return;
102	            }
103	
104	            $universe = $component->universeIds();
105	            $selected = collect((array) $component->getState())
106	                ->map(fn (mixed $id): string => is_numeric($id) ? (string) (int) $id : '')
107	                ->filter()
108	                ->values()
109	                ->all();
110	            $selected = array_values(array_intersect($selected, $universe));
111	
112	            // sync ristretto all'universo: non tocca gli id di relazioni
113	            // condivise che appartengono ad altre istanze del campo
114	            $relation = self::relationOf($record, $name);
115	            $relation->detach(array_values(array_diff($universe, $selected)));
116	            $relation->syncWithoutDetaching($selected);
117	        });
118	
119	        return $this;
120	    }
121	
122	    /**
123	     * Categorie iniettate dal chiamante (già filtrate/eager-loaded), al posto
124	     * della query non filtrata su $categoryModel. Accetta anche una closure
125	     * (con eventuale iniezione di Get) per riscoprire le categorie ad ogni
126	     * render, quando il filtro dipende da un altro campo reattivo del form.
127	     *
128	     * @param iterable<Model>|\Closure $categories
129	     */
130	    public function categories(iterable|\Closure $categories): static
131	    {
132	        $this->categories = $categories instanceof \Closure ? $categories : self::toList($categories);
133	
134	        return $this;
135	    }
136	
137	    /**
138	     * Item iniettati dal chiamante (già filtrati/eager-loaded), al posto
139	     * della query non filtrata su $itemModel. Accetta anche una closure, vedi
140	     * {@see self::categories()}.
141	     *
142	     * @param iterable<Model>|\Closure $items
143	     */
144	    public function items(iterable|\Closure $items): static
145	    {
146	        $this->items = $items instanceof \Closure ? $items : self::toList($items);
147	
148	        return $this;
149	    }
150	
151	    /**
152	     * @param iterable<Model> $models
153	     * @return list<Model>
154	     */
155	    private static function toList(iterable $models): array
156	    {
157	        return array_values($models instanceof Collection ? $models->all() : [...$models]);
158	    }
159	
160	    /**
161	     * Valuta array|Closure già ristretto a "iterable<Model>" da {@see self::categories()}/{@see self::items()};
162	     * la closure può iniettare Get per filtrare in base allo stato reattivo del form.
163	     *
164	     * @param list<Model>|\Closure $value
165	     * @return iterable<Model>
166	     */
167	    private function evaluateModels(array|\Closure $value): iterable
168	    {
169	        /** @var iterable<Model> $result */
170	        $result = $this->evaluate($value);
171	
172	        return $result;
173	    }
174	
175	    /**
176	     * Categorie con i loro item, pronte per la view.
177	     *
178	     * @return list<array{key:string,label:string,ids:list<string>,options:list<array{id:string,label:string}>}>
179	     */
180	    public function getGroups(): array
181	    {
182	        $keyOf = static fn (Model $model): int => is_numeric($key = $model->getKey()) ? (int) $key : 0;
183	        $nameOf = static fn (Model $model): string => is_scalar($name = $model->getAttribute('name')) ? (string) $name : '';
184	
185	        $categoryModel = $this->categoryModel;
186	        $itemModel = $this->itemModel;
187	
188	        $categories = $this->categories !== null ? self::toList($this->evaluateModels($this->categories)) : $categoryModel::query()->get()->all();
189	
190	        $items = $this->items !== null ? self::toList($this->evaluateModels($this->items)) : $itemModel::query()->get()->all();
191	
192	        /** @var array<int, string> $categoryNames */
193	        $categoryNames = collect($categories)
194	            ->mapWithKeys(fn (Model $category): array => [$keyOf($category) => $nameOf($category)])
195	            ->all();
196	
197	        // item raggruppati per categoria; ogni gruppo ordinato per nome (tradotto)
198	        $groups = collect($items)
199	            ->sortBy($nameOf)
200	            ->groupBy(fn (Model $item): int|string => is_numeric($fk = $item->getAttribute($this->categoryForeignKey)) ? (int) $fk : '');
201	
202	        $result = [];
203	
204	        foreach ($groups as $categoryId => $categoryItems) {
205	            /** @var list<array{id:string,label:string}> $options */
206	            $options = $categoryItems->map(fn (Model $item): array => [
207	                'id' => (string) $keyOf($item),
208	                'label' => $nameOf($item),
209	            ])->values()->all();
210	
211	            $result[] = [
212	                'key' => (string) $categoryId,
213	                'label' => $categoryNames[$categoryId] ?? $this->noCategoryLabel,
214	                'ids' => array_column($options, 'id'),
215	                'options' => $options,
216	            ];
217	        }
218	
219	        return $result;
220	    }
221	
222	    /**
223	     * Tutti gli id di item offerti come opzioni dal campo, a prescindere dalla
224	     * categoria: è l'universo su cui load/save operano quando la relazione è
225	     * condivisa con altre istanze filtrate diversamente.
226	     *
227	     * @return list<string>
228	     */
229	    private function universeIds(): array
230	    {
231	        return array_values(collect($this->getGroups())->flatMap(fn (array $group): array => $group['ids'])->all());
232	    }
233	
234	    /**
235	     * @return BelongsToMany<Model, Model>
236	     */
237	    private static function relationOf(Model $record, string $name): BelongsToMany
238	    {
239	        /** @var BelongsToMany<Model, Model> $relation */
240	        $relation = $record->{$name}();
241	
242	        return $relation;
243	    }
244	}
