30	
31	class ProductForm
32	{
33	    public static function configure(Schema $schema): Schema
34	    {
35	        return $schema
36	            ->components([
37	                // solo informativo: per i prodotti la destinazione è stabilita
38	                // dalla categoria padre della collezione selezionata
39	                Category1Select::section(
40	                    TextEntry::make('category1_info')
41	                        ->hiddenLabel()
42	                        ->state(function (Get $get): string {
43	                            $category1 = self::category1From($get);
44	
45	                            return $category1 !== null ? $category1->name : '—';
46	                        })
47	                        ->size(TextSize::Large)
48	                        ->badge(),
49	                ),
50	                NameAndId::make($schema),
51	
52	                Section::make(__('product.sections.classification'))
53	                    ->columns(2)
54	                    ->schema([
55	                        Select::make('category_2_id')
56	                            ->label(__('product.category_2'))
57	                            ->options(fn (): array => Category2::query()->pluck('name', 'id')->map(fn (mixed $name): string => is_scalar($name) ? (string) $name : '')->all())
58	                            ->default(fn (): mixed => request()->query('category_2'))
59	                            ->required()
60	                            ->searchable()
61	                            // reattivo: aggiorna il campo informativo "Destinazione"
62	                            ->live(),
63	                        Select::make('parent_id')
64	                            ->label(__('product.parent'))
65	                            ->helperText(__('product.parent_helper'))
66	                            // gerarchia a un solo livello: candidati padre sono solo i prodotti
67	                            // senza padre a loro volta; escluso il record stesso in edit
68	                            ->options(fn (?Product $record): array => Product::query()
69	                                ->whereNull('parent_id')
70	                                ->when($record !== null, fn ($query) => $query->whereKeyNot($record?->getKey()))
71	                                ->with('category2')
72	                                ->orderBy('name->it')
73	                                ->get()
74	                                ->mapWithKeys(fn (Product $parent): array => [
75	                                    $parent->id => $parent->catalogName(),
76	                                ])
77	                                ->all())
78	                            ->searchable()
79	                            // un wrapper con moduli non può a sua volta avere un padre
80	                            ->hidden(fn (?Product $record): bool => $record !== null && $record->modules()->exists()),
81	                        Select::make('product_type_id')
82	                            ->label(__('product.product_type'))
83	                            ->options(fn (): array => ProductType::query()->pluck('name', 'id')->map(fn (mixed $name): string => is_scalar($name) ? (string) $name : '')->all())
84	                            ->required()
85	                            ->searchable()
86	                            // reattivo: il cambio di tipologia rigenera l'editor degli attributi
87	                            // e (ri)valuta l'alert orfani sottostante
88	                            ->live(),
89	                        Select::make('environments')
90	                            ->label(__('product.environments'))
91	                            ->relationship('environments', 'name')
92	                            ->options(fn (): array => Environment::query()->pluck('name', 'id')->map(fn (mixed $name): string => is_scalar($name) ? (string) $name : '')->all())
93	                            ->multiple()
94	                            ->searchable()
95	                            ->preload(),
96	                    ]),
97	                Section::make(__('product.sections.materials_fabrics'))
98	                    ->columns(2)
99	                    ->schema([
100	                        // checkbox annidati per categoria: la relazione è salvata
101	                        // sempre a livello di singolo materiale/tessuto.
102	                        // Categorie e item sono ristretti alla Destinazione (Category1)
103	                        // del prodotto, risolta dal category_2_id selezionato sopra.
104	                        NestedCheckboxSelect::make('materials')
105	                            ->label(__('material.model_plural'))
106	                            ->relationship('materials', Material::class, MaterialCategory::class, 'material_category_id', __('material.no_category'))
107	                            ->categories(fn (Get $get): iterable => self::materialCategoriesFrom($get))
108	                            ->items(fn (Get $get): iterable => self::materialsFrom($get)),
109	                        NestedCheckboxSelect::make('fabrics')
110	                            ->label(__('fabric.model_plural'))
111	                            ->relationship('fabrics', Fabric::class, FabricCategory::class, 'fabric_category_id', __('fabric.no_category'))
112	                            ->categories(fn (Get $get): iterable => self::fabricCategoriesFrom($get))
113	                            ->items(fn (Get $get): iterable => self::fabricsFrom($get)),
114	                    ]),
115	
116	                // solo i tag dei gruppi (product, entity) — vincolo rigido
117	                TagPicker::make((new Product())->getMorphClass(), TagTarget::Entity),
118	
119	
120	                // alert orfani: avvisa, al cambio tipologia, dei valori PIM che si
121	                // perderebbero perché non più previsti dal nuovo schema (vedi core).
122	                OrphanAttributesAlert::reactive($schema, self::schemaResolver()),
123	
124	                // la section "Dati tecnici" (con le tabs per gruppo) è renderizzata
125	                // direttamente dal componente
126	                AttributesEditorSection::reactive($schema, self::schemaResolver())->columnSpanFull(),
127	
128	            ]);
129	    }
130	
131	    /**
132	     * Destinazione (Category1) del prodotto, risolta dalla categoria di
133	     * secondo livello selezionata nel form. Condivisa dal campo informativo
134	     * "Destinazione" e dai filtri di materiali/tessuti.
135	     */
136	    private static function category1From(Get $get): ?Category1
137	    {
138	        $categoryId = $get('category_2_id');
139	
140	        if (! is_numeric($categoryId)) {
141	            return null;
142	        }
143	
144	        return Category2::query()->find((int) $categoryId)?->category1;
145	    }
146	
147	    /**
148	     * @return iterable<MaterialCategory>
149	     */
150	    private static function materialCategoriesFrom(Get $get): iterable
151	    {
152	        $category1 = self::category1From($get);
153	
154	        return $category1 !== null ? $category1->materialCategories : [];
155	    }
156	
157	    /**
158	     * @return iterable<Material>
159	     */
160	    private static function materialsFrom(Get $get): iterable
161	    {
162	        $category1 = self::category1From($get);
163	
164	        return $category1 !== null
165	            ? $category1->materialCategories->flatMap(fn (MaterialCategory $category): iterable => $category->materials)
166	            : [];
167	    }
168	
169	    /**
170	     * @return iterable<FabricCategory>
171	     */
172	    private static function fabricCategoriesFrom(Get $get): iterable
173	    {
174	        $category1 = self::category1From($get);
175	
176	        return $category1 !== null ? $category1->fabricCategories : [];
177	    }
178	
179	    /**
180	     * @return iterable<Fabric>
181	     */
182	    private static function fabricsFrom(Get $get): iterable
183	    {
184	        $category1 = self::category1From($get);
185	
186	        return $category1 !== null
187	            ? $category1->fabricCategories->flatMap(fn (FabricCategory $category): iterable => $category->fabrics)
188	            : [];
189	    }
190	
191	    /**
192	     * Resolver dello schema attributi corrente dal form state: legge
193	     * product_type_id e ritorna la AttributeSchema della tipologia selezionata
194	     * (o null). Condiviso da AttributesEditorSection::reactive() e OrphanAttributesAlert.
195	     *
196	     * @return \Closure(Get): ?AttributeSchema
197	     */
198	    private static function schemaResolver(): \Closure
199	    {
200	        return static function (Get $get): ?AttributeSchema {
201	            $class = self::schemaClassFor($get('product_type_id'));
202	
203	            return $class !== null ? new $class() : null;
204	        };
205	    }
206	
207	    /**
208	     * FQN della AttributeSchema associata a una tipologia, o null se non risolvibile.
209	     *
210	     * @return class-string<AttributeSchema>|null
211	     */
212	    private static function schemaClassFor(mixed $productTypeId): ?string
213	    {
214	        if (! is_numeric($productTypeId)) {
215	            return null;
216	        }
217	
218	        $class = ProductType::query()->find((int) $productTypeId)?->attribute_schema_class;
219	
220	        return is_string($class) && is_subclass_of($class, AttributeSchema::class) ? $class : null;
221	    }
222	}
